      if(works.some(x=>x.start<=start&&x.end>=end)){const em=document.createElement('em');em.className=works.some(x=>x.source&&x.start<=start&&x.end>=end)?'source-emphasis':works.some(x=>x.label&&x.start<=start&&x.end>=end)?'film-label':'work-title';em.append(node);node=em;}
      if(sourceFormats.some(x=>x.kind==='em'&&x.start<=start&&x.end>=end)&&!works.some(x=>x.start<=start&&x.end>=end)){const em=document.createElement('em');em.className='source-emphasis';em.append(node);node=em;}
      if(sourceFormats.some(x=>x.kind==='strong'&&x.start<=start&&x.end>=end)){const strong=document.createElement('strong');strong.className='source-emphasis';strong.append(node);node=strong;}
